export const hostUnmigratedFiles = Object.freeze(referenceFiles.map(([file, referenceBlob, responsibility]) => {
  const disposition = migrationOwners[responsibility];
  if (disposition === undefined) throw new Error("A frozen reference file requires its explicit C1 migration owner.");
  return Object.freeze({ file, referenceBlob, destinations: disposition.destinations, retiringUnit: disposition.retiringUnit });
}));
